      "sender_type": "AGENT",
      "sender_id": "usr_agent",
      "message_type": "text",
      "content": "Olá, Mitch Saki! Sou o assistente da *Realizze Travel*. Como posso ajudar você a planejar sua viagem dos sonhos hoje?",
      "status": "delivered",
      "created_at": "2026-08-28T19:45:20.000Z"
